manual.p:
Pike has three facilities for choosing between alternatives: the
if statement, the switch statement, and the ? :
operator.

manual.pi:
if(this_user == file_owner)
  allow_access();
else
{
  deny_access();
  send_message(file_owner, "Warning: " + this_user +
               " tried to access your file.");
}

if(temperature < 200.0)
  burn(10);
else if(temperature < 300.0)
  burn(5);
else if(temperature < 400.0)
  burn(2);
else
  turn_off_heat();

if(command == "print")
  print(argument);
else if(command == "save")
  save(argument);
else if(command == "quit" || command == "exit")
  quit(argument);
else
  write("Unknown command.\n");

switch(command)
{
  case "print":
    print(argument);
    break;
  case "save":
    save(argument);
    break;
  case "quit":
  case "exit":
    quit(argument);
    break;
  default:
    write("Unknown command.\n");
    break;
}

if(a > b)
  max_value = a;
else
  max_value = b;
